#!/bin/sh
# Build the plugin library for both targets with zig cc (no Docker needed):
#   build/armv7/variant.so    Gen1 / Akai Force  (tested on a Force)
#   build/aarch64/variant.so  Gen2 (MPC Live III and kin)  (not tested on a Gen2 device)
# Needs: WRAPPER = the wrapper/ folder of an mpc-vst-plugins checkout, and vst/build/params.h generated by that checkout's
# tools/gen_vst.py from vst/vst.json (the wrapper and params.h must come from the same checkout).
# Package with that checkout's tools/release.py (apostrophe-safe: the vendor name is L'Cronx).
set -e
cd "$(dirname "$0")"
: "${WRAPPER:?set WRAPPER to the wrapper/ folder of mpc-vst-plugins}"
mkdir -p build/inc build/armv7 build/aarch64
[ -d build/inc/alsa ] || cp -r /usr/include/alsa build/inc/
for t in armv7:arm-linux-gnueabihf aarch64:aarch64-linux-gnu; do
  arch=${t%%:*}; tgt=${t#*:}
  python3 -m ziglang cc -target "$tgt.2.31" -O2 -Wall -Wextra -Wno-unused-parameter -fPIC -shared -s \
    -fvisibility=hidden -std=gnu11 -Isrc -Ivst/build -Ibuild/inc -I"$WRAPPER" \
    src/engine.c "$WRAPPER/vst2_wrap.c" -lm -lpthread -ldl -o "build/$arch/variant.so"
  echo "built build/$arch/variant.so"
done
